import java.util.*;class SweepingWatershedTest{public static void main(String[]a){var high=new RiverRibbon.Point(100,100,2,650,20);var low=new RiverRibbon.Point(200,200,4,72,80);var original=new RiverRibbon.Network(List.of(new RiverRibbon.Segment(high,low,2)));var grown=original.growDownstream(1.2,62).segments.get(0);if(grown.a().radius()!=2||grown.b().radius()<7||grown.a().discharge()!=20||grown.b().discharge()!=80)throw new AssertionError("Growth changes source or discharge");int n=128;var h=EnvironmentMap.filled(n*n,92);var normal=RiverMorphology.shape(RiverBroadCurveTest.path(),h,n,8,83,1);var broad=RiverMorphology.shape(RiverBroadCurveTest.path(),h,n,8,83,2);double normalDistance=999,broadDistance=999;for(var p:normal)normalDistance=Math.min(normalDistance,Math.hypot(p.x()-700,p.z()-300));for(var p:broad)broadDistance=Math.min(broadDistance,Math.hypot(p.x()-700,p.z()-300));if(broadDistance<normalDistance*1.2)throw new AssertionError("Sweep does not produce larger bend");System.out.println("PASS: mouth widens without changing flow, source stays narrow; bend setback "+normalDistance+" -> "+broadDistance);}}
